"use strict";
Object.defineProperty(exports, "__esModule", { value: true });
exports.getMaxEl = exports.insertHTMLToMaxEl = exports.insertHTML = exports.getElement = void 0;
function getElement(selector) {
    if (typeof selector === 'string')
        return document.querySelector(selector);
    return selector;
}
exports.getElement = getElement;
function insertHTML(target, html, where = 'afterbegin') {
    let el = getElement(target);
    el.insertAdjacentHTML(where, html);
}
exports.insertHTML = insertHTML;
function insertHTMLToMaxEl(html, where) {
    insertHTML(getMaxEl(), html, where);
}
exports.insertHTMLToMaxEl = insertHTMLToMaxEl;
/*
 * 获取页面中最大的块级元素, 没有的话则返回 body
 * */
function getMaxEl() {
    let allBlock = document.querySelectorAll('div,section,header,footer,nav,article,aside,p'), maxEl = document.body, maxArea = 0;
    Array.prototype.forEach.call(allBlock, item => {
        let height = item.offsetHeight, width = item.offsetWidth, area = height * width;
        if (area > maxArea) {
            maxArea = area;
            maxEl = item;
        }
    });
    return maxEl;
}
exports.getMaxEl = getMaxEl;
